/// A method with its params and result types.
public struct HabMethod<Params: Codable & Sendable, Result: Codable & Sendable>: Sendable {
    public let name: String
}

public enum HabMethods {
    /// First request on a control connection: agree a revision (spec 3.2).
    public static let habHello = HabMethod<HelloParams, Welcome>(name: "hab.hello")
    /// Client liveness; send every 15 s when idle (spec 3.5).
    public static let habPing = HabMethod<PingParams, Empty>(name: "hab.ping")
    /// The schema of this API. Its result is the schema document and carries no seq.
    public static let rpcDiscover = HabMethod<DiscoverParams, JSONValue>(name: "rpc.discover")
    /// Read the whole structure of the host.
    public static let structureGet = HabMethod<StructureGetParams, StructureResult>(name: "structure.get")
    /// Snapshot the objects in scope and start events (spec 3.5).
    public static let eventsSubscribe = HabMethod<SubscribeParams, StructureResult>(name: "events.subscribe")
    /// Write bytes to a pane's program as one write (spec 3.8).
    public static let paneInput = HabMethod<InputParams, Empty>(name: "pane.input")
    /// A single-use ticket, valid 30 s, to open a data connection (spec 5.2).
    public static let dataTicket = HabMethod<TicketParams, Ticket>(name: "data.ticket")
    /// Become the pane's size owner now (spec 6.3).
    public static let paneTake = HabMethod<PaneRef, OwnerResult>(name: "pane.take")
    /// Become the size owner only if the pane has none (spec 6.3).
    public static let paneRequest = HabMethod<PaneRef, OwnerResult>(name: "pane.request")
    /// Give up size ownership; the pane keeps its size (spec 6.3).
    public static let paneDisown = HabMethod<PaneRef, OwnerResult>(name: "pane.disown")
    /// Store this client's wanted size (spec 6.3).
    public static let paneSetDesiredSize = HabMethod<DesiredSizeParams, DesiredSizeResult>(name: "pane.set_desired_size")
    /// Send a fresh snapshot, or nudge the program to redraw (spec 6.7).
    public static let paneRedraw = HabMethod<RedrawParams, Empty>(name: "pane.redraw")
    /// Make a one-time pairing offer for a new device (transport.md 6.1). Needs the devices capability.
    public static let devicesPair = HabMethod<DevicesPairParams, PairingOffer>(name: "devices.pair")
    /// List the devices in the hab's trust store (transport.md 5). Needs the devices capability.
    public static let devicesList = HabMethod<DevicesListParams, DeviceList>(name: "devices.list")
    /// Revoke a device and close its connections (transport.md 6.6). Needs the devices capability.
    public static let devicesRevoke = HabMethod<DevicesRevokeParams, Empty>(name: "devices.revoke")
    /// Start a program in a new pane and file it as a session (spec 3.9).
    public static let sessionCreate = HabMethod<SessionCreateParams, SessionCreated>(name: "session.create")
    /// Start an exited session's harness again in a new pane, with its resume id.
    public static let sessionResume = HabMethod<SessionRef, SessionCreated>(name: "session.resume")
    /// Release a pane: a running program gets a hang-up first (spec 3.9).
    public static let paneClose = HabMethod<PaneRef, Empty>(name: "pane.close")
    /// Give a session a new name. A name another session holds is refused with conflict.
    public static let sessionRename = HabMethod<SessionRenameParams, Empty>(name: "session.rename")
    /// Remove a session record. A live pane keeps running, unfiled; pane.close ends a program.
    public static let sessionClose = HabMethod<SessionRef, Empty>(name: "session.close")
    /// Report whether the session is in focus on this client: marks done seen, and holds pushes while watched.
    public static let sessionFocus = HabMethod<SessionFocusParams, Empty>(name: "session.focus")
    /// Stop the agent's current turn through its adapter.
    public static let sessionInterrupt = HabMethod<SessionRef, Empty>(name: "session.interrupt")
    /// Send a message to the session's agent through its adapter, under the input rules.
    public static let sessionSend = HabMethod<SessionSendParams, Empty>(name: "session.send")
    /// Answer a pending request by id. A closed or expired id is refused with conflict.
    public static let approvalAnswer = HabMethod<ApprovalAnswerParams, Empty>(name: "approval.answer")
    /// Read a page of the session's chat messages from the transcript reader. Needs the transcripts capability.
    public static let chatPage = HabMethod<ChatPageParams, ChatMessages>(name: "chat.page")
    /// Start an upload of a file for a session; the bytes follow on their own channel.
    public static let attachmentPut = HabMethod<AttachmentPutParams, AttachmentStored>(name: "attachment.put")
    /// Fetch an attachment or its thumbnail.
    public static let attachmentGet = HabMethod<AttachmentGetParams, AttachmentData>(name: "attachment.get")
    /// Store an APNs device token for this device. Needs the push capability.
    public static let pushRegister = HabMethod<PushRegisterParams, Empty>(name: "push.register")
    /// Store a Live Activity token for the session this device tracks. Needs the push capability.
    public static let pushRegisterActivity = HabMethod<PushActivityParams, Empty>(name: "push.register_activity")
    /// Drop a push token. Needs the push capability.
    public static let pushUnregister = HabMethod<PushUnregisterParams, Empty>(name: "push.unregister")
    /// Raise a Flightdeck notification: a notice.raised event to subscribers, and a push where push is set up.
    public static let noticeRaise = HabMethod<NoticeRaiseParams, NoticeRaised>(name: "notice.raise")
    /// The latest usage reading of each harness account on this hab.
    public static let usageList = HabMethod<UsageListParams, UsageReadings>(name: "usage.list")
    /// CPU, memory, disk, battery and uptime of the host. Needs the host-stats capability.
    public static let habStats = HabMethod<HabStatsParams, HostStats>(name: "hab.stats")
    /// Read a page of a pane's shell commands, found by OSC 133 marks (spec 2.5). Needs the commands capability.
    public static let commandList = HabMethod<CommandListParams, CommandList>(name: "command.list")
    /// Read a run of one command's output from the holder's ring (spec 2.5). Needs the commands capability.
    public static let commandOutput = HabMethod<CommandOutputParams, CommandOutput>(name: "command.output")
    /// This hab's peers with their link state, and habs linked to it that it does not list (mesh.md 3, 4.3). Needs the mesh capability.
    public static let peersList = HabMethod<PeersListParams, PeerList>(name: "peers.list")
    /// Pin the device id a peer presented in place of the pinned one (transport.md 6.3). Needs the mesh capability.
    public static let peersAccept = HabMethod<PeersAcceptParams, PeerAccepted>(name: "peers.accept")
    /// Check the permission grants of the holders, from a probe pane, and of gff-hab (macos-identity.md 7.2). Needs the permissions capability.
    public static let habPermissions = HabMethod<PermissionsParams, Permissions>(name: "hab.permissions")
}

public enum HabNotification {
    public static let event = "event"
    public static let heartbeat = "heartbeat"
    public static let closing = "closing"
}

/// The data of an event, decoded by its type. Unknown types decode to `.unknown`.
public enum HabEvent: Sendable, Hashable {
    /// A project was created or changed.
    case projectUpdated(Project)
    /// A project was removed.
    case projectDeleted(Deleted)
    /// A session was created or changed, including its exit.
    case sessionUpdated(Session)
    /// A session record was removed.
    case sessionDeleted(Deleted)
    /// A pane appeared or changed.
    case paneUpdated(Pane)
    /// A pane is gone.
    case paneDeleted(Deleted)
    /// The pane's size owner changed (spec 6.5).
    case paneOwner(PaneOwner)
    /// A client sent input; at most once per second per client (spec 7.1).
    case paneActivity(PaneActivity)
    /// A pane's agent state changed (harness-adapters.md, State event model). The id is the pane id.
    case agentState(AgentState)
    /// A pane rang the bell; at most once per second per pane. Ephemeral.
    case paneBell(PaneBell)
    /// A pane printed; at most once per second per pane, for activity marks. Ephemeral.
    case paneOutput(PaneOutput)
    /// A chat message was appended or changed; the id is the message id. Ephemeral.
    case chatMessage(ChatMessage)
    /// The agent's turn ended; the id is the session id. Ephemeral.
    case sessionTurnEnd(TurnEnd)
    /// An account's usage reading changed; the id is the account key. Ephemeral.
    case usageUpdated(UsageAccount)
    /// A pane's command started or ended; the id is the pane id (spec 2.5). Ephemeral.
    case commandUpdated(Command)
    /// A peer's link state changed; the id is the peer's label (mesh.md 4.3). Host scope only. Ephemeral.
    case peerUpdated(Peer)
    /// A notice was raised (notice.raise); the id is the notice id. Ephemeral.
    case noticeRaised(Notice)
    case unknown(type: String, data: JSONValue)

    public init(_ event: Event) throws {
        switch event.type {
        case "project.updated": self = .projectUpdated(try event.data.decode(Project.self))
        case "project.deleted": self = .projectDeleted(try event.data.decode(Deleted.self))
        case "session.updated": self = .sessionUpdated(try event.data.decode(Session.self))
        case "session.deleted": self = .sessionDeleted(try event.data.decode(Deleted.self))
        case "pane.updated": self = .paneUpdated(try event.data.decode(Pane.self))
        case "pane.deleted": self = .paneDeleted(try event.data.decode(Deleted.self))
        case "pane.owner": self = .paneOwner(try event.data.decode(PaneOwner.self))
        case "pane.activity": self = .paneActivity(try event.data.decode(PaneActivity.self))
        case "agent.state": self = .agentState(try event.data.decode(AgentState.self))
        case "pane.bell": self = .paneBell(try event.data.decode(PaneBell.self))
        case "pane.output": self = .paneOutput(try event.data.decode(PaneOutput.self))
        case "chat.message": self = .chatMessage(try event.data.decode(ChatMessage.self))
        case "session.turn_end": self = .sessionTurnEnd(try event.data.decode(TurnEnd.self))
        case "usage.updated": self = .usageUpdated(try event.data.decode(UsageAccount.self))
        case "command.updated": self = .commandUpdated(try event.data.decode(Command.self))
        case "peer.updated": self = .peerUpdated(try event.data.decode(Peer.self))
        case "notice.raised": self = .noticeRaised(try event.data.decode(Notice.self))
        default: self = .unknown(type: event.type, data: event.data)
        }
    }
}

/// The first byte of a data connection frame. A frame is this byte, a 4-byte big-endian
/// payload length, then the payload.
public enum FrameKind: UInt8, Sendable {
    /// JSON payload: `DataHello`.
    case hello = 1
    /// JSON payload: `DataWelcome`.
    case welcome = 2
    /// JSON payload: `DataReject`.
    case reject = 3
    /// Binary payload: 8-byte big-endian offset it covers, 1-byte encoding name length, encoding name, screen bytes.
    case snapshot = 4
    /// Binary payload: 8-byte big-endian offset of the first byte, then program output.
    case bytes = 5
    /// JSON payload: `ResizeFrame`.
    case resize = 6
    /// JSON payload: `ExitedFrame`.
    case exited = 7
    /// JSON payload: `CreditFrame`.
    case credit = 8
}

/// Any JSON value, for fields whose shape the receiver picks.
public enum JSONValue: Codable, Sendable, Hashable {
    case null
    case bool(Bool)
    /// A whole number that fits Int64. Kept exact, unlike a Double.
    case int(Int64)
    /// A whole number above Int64.max, such as a large offset. Kept exact.
    case uint(UInt64)
    /// Any other number.
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])

    public init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() {
            self = .null
        } else if let v = try? c.decode(Bool.self) {
            self = .bool(v)
        } else if let v = try? c.decode(Int64.self) {
            self = .int(v)
        } else if let v = try? c.decode(UInt64.self) {
            self = .uint(v)
        } else if let v = try? c.decode(Double.self) {
            self = .number(v)
        } else if let v = try? c.decode(String.self) {
            self = .string(v)
        } else if let v = try? c.decode([JSONValue].self) {
            self = .array(v)
        } else {
            self = .object(try c.decode([String: JSONValue].self))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.singleValueContainer()
        switch self {
        case .null: try c.encodeNil()
        case .bool(let v): try c.encode(v)
        case .int(let v): try c.encode(v)
        case .uint(let v): try c.encode(v)
        case .number(let v): try c.encode(v)
        case .string(let v): try c.encode(v)
        case .array(let v): try c.encode(v)
        case .object(let v): try c.encode(v)
        }
    }

    /// Decodes this value as T, by a round trip through JSON.
    public func decode<T: Decodable>(_ type: T.Type) throws -> T {
        try JSONDecoder().decode(T.self, from: JSONEncoder().encode(self))
    }
}
